head.script:
scwin.screenId = "jldfil05103_tip";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.util.getCookie('alertListPre1Day') !== 'alertListPre1Day' && $c.util.getCookie('alertListPre1Week') !== 'alertListPre1Week') {
            (($c.util.getComponent('divAlertListPre')) && ($c.util.getComponent('divAlertListPre')).removeClass ? ($c.util.getComponent('divAlertListPre')).removeClass('pop_wrap') : console.error('[sdd] removeClass 미지원 컴포넌트: divAlertListPre'));
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05103_tip.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05103_tip.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_extend1Week_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_extend1Week_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_extend1Week_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.extend1Week()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05103_tip.btn_extend1Week_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_extend1Day_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_extend1Day_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_extend1Day_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.extend1Day()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05103_tip.btn_extend1Day_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.extend1Day
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.extend1Day = function () {
    /* sdd-asis-lifecycle:begin extend1Day — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.setSessionStorage("alertListPre1Day", "alertListPre1Day");
    hideLayer("#divAlertListPre");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.extend1Week
 * @author Inswave
 * @date 2026. 09. 29
 * @param chkVal
 * @returns
 * @hidden N
*/
scwin.extend1Week = function (chkVal) {
    /* sdd-asis-lifecycle:begin extend1Week — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.setCookie("alertListPre1Week", "alertListPre1Week", 6);
    hideLayer("#divAlertListPre");
    /* sdd-asis-lifecycle:end */
};
